'use strict';
const Narrative=(()=>{
const C=LifeContent;
function hash(seed,n,salt=0){let x=(seed^Math.imul(n+1,2654435761)^Math.imul(salt+3,1597334677))>>>0;x=Math.imul(x^(x>>>16),2246822507);x=Math.imul(x^(x>>>13),3266489909);return (x^(x>>>16))>>>0}
function at(s,arr,salt=0){return typeof NarrativeVoice==='undefined'?arr[hash(s.seed,s.diary.sequence,salt)%arr.length]:NarrativeVoice.pick(s,arr,salt)}
function name(s,salt){return typeof FantasyNames!=='undefined'?FantasyNames.npc(s,salt):NAMES[(hash(s.seed,0,0)+salt*5)%NAMES.length]}
function ensure(s){const home=FamilyWorld.ensure(s),guardian=FamilyWorld.primary(s),sibling=FamilyWorld.chooseRelative(s,1);if(!s.diary){s.diary={version:1,sequence:0,entries:[],arcs:{},memories:[],people:[{id:'guardian',memberId:guardian.id,name:guardian.name,role:guardian.role,trust:guardian.trust},{id:'family-sibling',memberId:sibling.id,name:sibling.name,role:sibling.role,trust:sibling.trust},{id:'neighbor',name:name(s,2),role:'เพื่อนบ้านจาก'+KINGDOMS[s.kingdom][0],trust:30},{id:'mentor',name:name(s,3),role:'ผู้แนะนำวิชา',trust:35}],energy:75,comfort:60,social:50,yearBudget:{year:-1,count:0},recent:[],interaction:{},lastJourney:-1}}
const d=s.diary;let g=d.people.find(p=>p.id==='guardian');if(!g){g={id:'guardian',memberId:guardian.id,name:guardian.name,role:guardian.role,trust:guardian.trust};d.people.unshift(g)}else{g.memberId=guardian.id;g.name=guardian.name;g.role=guardian.role;g.trust=guardian.trust}let sib=d.people.find(p=>p.id==='family-sibling');if(!sib)d.people.push({id:'family-sibling',memberId:sibling.id,name:sibling.name,role:sibling.role,trust:sibling.trust});else{sib.memberId=sibling.id;sib.name=sibling.name;sib.role=sibling.role}if(s.partner){const partner=FamilyWorld.addPartner(s,s.partner);let p=d.people.find(p=>p.id==='partner');if(!p){p={id:'partner',memberId:'partner',name:partner.name,role:'คู่ชีวิต',trust:Math.min(100,s.bond)};d.people.push(p)}else{p.memberId='partner';p.name=partner.name}}for(let i=0;i<Math.min(s.children,3);i++){const child=FamilyWorld.addChild(s,i);const found=d.people.find(p=>p.id==='child-'+i);if(found)found.memberId=child.id;if(!found)d.people.push({id:'child-'+i,memberId:child.id,name:child.name,role:'ลูก',trust:child.trust})}if(typeof LifeBonds!=='undefined')LifeBonds.sync(s,d);return d}
function stage(s){const age=Engine.biological(s);return age<4?'baby':age<13?'child':age<18?'youth':age<60?'adult':'elder'}
function memory(s){const d=ensure(s),m=d.memories;if(!m.length)return '';const picked=at(s,m,33);return 'ระหว่างนั้นคุณนึกถึงเรื่อง “'+picked.title+'” ที่อายุ '+picked.age+' ปี ครั้งนั้นคุณเลือก'+picked.choice+' และ'+picked.result+' เรื่องเก่าไม่ได้หายไปเพียงเพราะผ่านหน้าถัดมาแล้ว'}
function person(s){const d=ensure(s),guardian=d.people.find(p=>p.id==='guardian'&&(!p.memberId||FamilyWorld.list(s).find(m=>m.id===p.memberId)?.alive));if(Engine.biological(s)<13&&guardian)return guardian;if(s.partner&&FamilyWorld.partnerAlive(s)){const partner=d.people.find(p=>p.id==='partner');if(partner)return partner}const known=d.people.filter(p=>p.id!=='guardian'&&p.alive!==false&&(typeof LifeBonds==='undefined'||p.memberId||p.bondId)&&(!p.memberId||FamilyWorld.list(s).find(m=>m.id===p.memberId)?.alive));return at(s,known.length?known:[guardian||d.people[0]],14)}
function context(s){const d=ensure(s),fraction=s.journey?.fraction||0;const season=C.seasons[(Math.floor(s.age*4+(s.calendar?.quarter||0)+fraction*4)+s.kingdom)%4];const phase=C.phases[d.sequence%5];return {season,phase,setting:at(s,C.kingdoms[s.kingdom],2),home:s.race!==0&&typeof SpeciesSociety!=='undefined'?SpeciesSociety.home(s):C.homes[s.rank],food:at(s,C.foods,s.kingdom+4),...WorldLore.context(s,d.sequence)}}
function needs(s,d){if(d.energy<35)return 'ร่างกายล้าจนคุณวางของผิดที่อยู่สองครั้ง คุณจึงยอมลดงานและหาเวลานั่งพักจริง ๆ';if(s.health<40)return 'คุณทำทุกอย่างช้าลงกว่าที่ตั้งใจ และจัดที่นั่งให้พักได้ระหว่างทาง สุขภาพทำให้แผนวันนี้ต้องเผื่อพื้นที่ไว้';if(s.gold<500)return 'ก่อนจ่ายเงิน คุณนับทองในถุงอีกครั้งแล้วเลือกสิ่งจำเป็นก่อน ของที่อยากได้ยังรอได้';if(d.social<35)return 'คุณรู้ตัวว่าไม่ได้คุยกับใครนานพอ จึงเริ่มจากทักคนที่เดินผ่านแทนการรีบกลับเงียบ ๆ';if(s.joy<35)return 'เรื่องที่เคยสนุกดูห่างออกไปนิดหนึ่ง วันนี้คุณจึงตั้งเป้าเพียงกินให้อิ่มและผ่านวันไปโดยไม่ฝืนตัวเอง';return ''}
function append(s,entry){if(typeof SpeciesSociety!=='undefined')entry=SpeciesSociety.narrative(s,entry);if(typeof Ecology!=='undefined')entry=Ecology.entry(s,entry);const d=ensure(s);if(typeof NarrativeVoice!=='undefined'&&!NarrativeVoice.prepare(s,entry))return null;if(typeof FaithWorld!=='undefined'&&entry.deityMark===undefined&&entry.kind==='faith')entry.deityMark=s.faith?.chosen||null;if(typeof FaithWorld!=='undefined'&&entry.key?.startsWith('decision-faith-'))entry.deityMark=EVENTS.find(e=>e.id===entry.key.slice(9))?.faithOnly||null;entry.id=d.sequence++;entry.age=s.age;if(typeof WorldTimeline!=='undefined')entry.worldYear=WorldTimeline.year(s);if(typeof WorldTimeline!=='undefined'&&entry.worldThreat===undefined)entry.worldThreat=WorldTimeline.impact(s).threats.find(t=>t.phase==='active'&&t.mode==='attack'&&t.harm>.3)?.id||null;entry.turn=s.turn;entry.month=entry.month||((s.calendar?.quarter||0)*3+1);entry.developmentAge=Engine.biological(s);entry.phase=entry.phase||context(s).phase;entry.season=entry.season||context(s).season;entry.where=KINGDOMS[s.kingdom][0];entry.realm=s.kingdom;if(typeof SceneCatalog!=='undefined'){const shot=SceneCatalog.resolve(s,entry);entry.scene=shot.environment}if(typeof VisualMemory!=='undefined')VisualMemory.capture(s,entry);d.entries.unshift(entry);if(typeof LifeLegacy!=='undefined')LifeLegacy.observe(s,entry);if(typeof VisualMemory!=='undefined')VisualMemory.trim(d.entries);if(d.entries.length>360)d.entries.length=360;d.recent.unshift(entry.key||entry.kind);d.recent.length=Math.min(d.recent.length,8);s.log.unshift({age:s.age,text:entry.title+' — '+entry.paragraphs.join(' '),kind:'daily',entryId:entry.id});if(s.log.length>1800)s.log.length=1800;return entry}
function effect(s,key){const d=ensure(s),year=Math.floor(Engine.biological(s));if(d.yearBudget.year!==year)d.yearBudget={year,count:0};if(d.yearBudget.count>=3)return;d.yearBudget.count++;if(key==='rest'){s.health=Math.min(100,s.health+1);d.energy=Math.min(100,d.energy+8);d.comfort=Math.min(100,d.comfort+2)}else if(key==='work'){s.wisdom=Math.min(100,s.wisdom+1);d.energy=Math.max(15,d.energy-3);d.social=Math.max(0,d.social-2);d.comfort=Math.max(0,d.comfort-1)}else if(key==='bond'){s.bond=Math.min(100,s.bond+1);d.social=Math.min(100,d.social+6);d.comfort=Math.min(100,d.comfort+2)}else if(key==='train'){s[s.focus]=Math.min(100,s[s.focus]+1);d.energy=Math.max(15,d.energy-2)}else s.joy=Math.min(100,s.joy+1)}
function passage(s,reason='time'){if(s.dead)return null;const d=ensure(s),v=context(s),age=Engine.biological(s),st=stage(s);let title='',paragraphs=[],kind='',key='',fx='joy';if(typeof Ecology!=='undefined'&&s.race!==0&&!d.entries.length&&age<2){const first=Ecology.growth(s,0,FamilyWorld.primary(s).name);return append(s,{...first,key:'birth'})}if(typeof Ecology!=='undefined'&&Ecology.profile(s).strict){const data=Ecology.daily(s),page=append(s,data);effect(s,s.job!==null&&age>=18?'work':age<6?'bond':'joy');return page}
if(d.entries.length&&typeof LifeStories!=='undefined'){const story=LifeStories.next(s);if(story){const entry=append(s,story);effect(s,story.kind==='relationship'?'bond':story.kind==='work'?'work':'joy');return entry}}
if(!d.entries.length&&age<4){title='บ้านหลังแรกในโลกใบใหม่';kind='home';key='birth';paragraphs=[v.setting+' คุณเริ่มรู้จักโลกจากกลิ่นอาหาร ผิวผ้าห่ม และเสียงที่เรียกหาอยู่ใกล้ ๆ','บ้านของคุณคือ'+v.home+' ใน'+KINGDOMS[s.kingdom][0]+' '+FamilyWorld.primary(s).name+' ผู้เป็น'+FamilyWorld.primary(s).role+' กับสมาชิกอีก '+(FamilyWorld.list(s).length-1)+' คนช่วยกันจัดบ้านให้มีที่สำหรับชีวิตใหม่ '+FamilyWorld.primary(s).name+'มีอาชีพ'+FamilyWorld.primary(s).occupation+' และชอบ '+FamilyWorld.primary(s).trait+''];}
else if(st==='baby'){const a=at(s,age<1&&C.babyEarly?C.babyEarly:C.stages.baby,4);title=a[0];kind='home';key='baby-'+a[0];paragraphs=[v.setting+' '+a[1],a[2]];fx='bond'}
else {
const categories=['daily','work','relationship','arc','training','heritage','memory','home'];kind=categories[d.sequence%categories.length];
if(kind==='work'&&(s.job===null||age<16))kind='daily';if(kind==='memory'&&!d.memories.length)kind='arc';
if(kind==='daily'){const a=at(s,C.stages[st],7);title=a[0];paragraphs=[v.setting+' '+a[1],a[2]];key='daily-'+a[0];fx=st==='elder'?'rest':'joy'}
if(kind==='work'){const task=at(s,C.jobs[s.job],8);title='วันทำงานของ'+JOBS[s.job][0];paragraphs=[v.setting+' วันนี้คุณ'+task,'คุณเก็บอุปกรณ์เมื่อจบงาน ตรวจว่าไม่มีอะไรค้างให้คนต่อไปต้องแก้แทน '+(s.gold<20?'รายได้ยังต้องเก็บไว้สำหรับค่าใช้จ่ายที่จำเป็น':'คุณจดสิ่งที่ทำได้ดีและสิ่งที่ยังต้องฝึกไว้ในสมุด')+' ผลงานของวันหนึ่งอาจเล็ก แต่ทุกวันกำลังสร้างความชำนาญ'];key='work-'+s.job+'-'+C.jobs[s.job].indexOf(task);fx='work'}
if(kind==='relationship'){const p=person(s);p.trust=Math.min(100,p.trust+1);if(p.memberId)FamilyWorld.adjust(s,p.memberId,1);title='เวลาข้าง ๆ '+p.name;paragraphs=typeof LifeStories==='undefined'?[v.setting+' คุณใช้เวลาฟังเรื่องที่'+p.name+'อยากเล่า']:LifeStories.dialogue(s,p,'talk');if(!paragraphs.length){title='ระลึกถึงคนที่เคยอยู่ข้างกัน';paragraphs=['คุณพบของที่เก็บไว้จากคนในบ้านและจดเรื่องที่ยังจำได้','ความทรงจำครั้งนี้ไม่ได้ทำให้เขากลับมา แต่ช่วยให้เห็นว่าสิ่งที่เคยทำร่วมกันอยู่ในชีวิตคุณอย่างไร']}key='relationship-'+p.id;fx='bond'}
if(kind==='arc'){let pool=C.arcs.filter(a=>a.min<=age&&(!Number.isFinite(a.max)||age<=a.max)&&(!a.needsJob||s.job!==null)&&(!a.needsPartner||FamilyWorld.partnerAlive(s))&&(!a.needsChild||FamilyWorld.list(s).some(m=>m.alive&&m.id.startsWith('child-')))&&(d.arcs[a.id]||0)<a.beats.length);const active=pool.filter(a=>d.arcs[a.id]>0);if(active.length&&hash(s.seed,d.sequence,17)%3!==0)pool=active;if(pool.length){const a=at(s,pool,18),beat=d.arcs[a.id]||0;title=a.title;paragraphs=[v.setting+' '+a.beats[beat],beat===2?'เมื่อเรื่องนี้เสร็จลง คุณได้เก็บบางอย่างมากกว่าของใช้หรือคำตอบ มันกลายเป็นรายละเอียดเล็ก ๆ ที่ทำให้ที่นี่เป็นบ้านของคุณ':'คุณเก็บรายละเอียดนี้ไว้ในใจ เรื่องเล็ก ๆ บางเรื่องยังต้องรอเวลา ก่อนจะรู้ว่ามันจะไปจบตรงไหน'];d.arcs[a.id]=beat+1;key='arc-'+a.id+'-'+beat;fx=a.effects.bond?'bond':a.effects.wisdom?'work':'joy'}else kind='home'}
if(kind==='training'){title='สิ่งที่ค่อย ๆ ฝึกจนเป็นตัวเรา';paragraphs=[v.setting+' '+at(s,C.focus[s.focus],19),age<16?'คุณยังทำได้ไม่สม่ำเสมอ แต่เริ่มสังเกตว่ามือที่เคยสั่นนิ่งขึ้นนิดหนึ่ง คนข้าง ๆ เตือนว่าอย่าเปรียบเทียบวันแรกของตนกับคนที่ฝึกมาหลายปี':'คุณลองวิธีใหม่เพียงอย่างเดียวแล้วจดผลไว้ ความก้าวหน้าไม่ได้ดังเหมือนการชนะในลานประลอง บางครั้งเป็นเพียงการทำสิ่งเดิมโดยผิดน้อยลง'];key='training-'+s.focus+'-'+d.sequence%2;fx='train'}
if(kind==='heritage'){title='ชีวิตในร่างของ'+RACES[s.race][0];paragraphs=[v.setting+' '+C.races[s.race],Species.isDemon(s.race)?'บางคนยังมองคุณจากคำว่าปีศาจก่อนรู้จักชื่อ แต่คนที่เจอกันทุกวันเริ่มทักคุณด้วยเรื่องที่ทำและของที่ชอบ โลกไม่ได้เปลี่ยนทั้งหมด ทว่าถนนเส้นนี้ค่อย ๆ รู้จักคุณมากขึ้น':'คุณต้องปรับความเคยชินของเผ่าตนให้เข้ากับคนรอบข้าง และเรียนรู้ว่าสิ่งที่ธรรมดาสำหรับคุณอาจต้องอธิบายให้ผู้อื่นเข้าใจ'];key='heritage-'+s.race;fx='joy'}
if(kind==='memory'){title='เรื่องเมื่อครั้งนั้นยังอยู่ในวันนี้';paragraphs=[v.setting+' '+memory(s),s.flags.academy?'คุณเปิดสมุดจากสมัยเรียน และพบรอยแก้ที่เคยเขินจนอยากฉีกทิ้ง วันนี้มันช่วยให้จำได้ว่ามาไกลเพียงใด':s.flags.refugees?'เมื่อได้ยินเสียงรถขนเสบียง คุณนึกถึงขบวนคนที่เคยช่วยไว้ และขยับทางให้คนที่แบกของผ่านไปก่อน':'คุณจัดของกลับเข้าที่ สิ่งที่เกิดขึ้นแล้วไม่ได้บอกว่าต้องเป็นใครตลอดไป แต่มันเป็นส่วนหนึ่งของวิธีที่คุณมองคนตรงหน้า'];key='memory-'+d.memories[hash(s.seed,d.sequence,33)%d.memories.length].id;fx='joy'}
if(kind==='home'){title='มื้อหนึ่งในบ้านของคุณ';const child=FamilyWorld.list(s).find(m=>m.alive&&m.id.startsWith('child-')),childAge=child?Engine.ageEquivalent(FamilyWorld.age(s,child),child.race):0;paragraphs=['เมื่อกลับถึง'+v.home+' คุณวางของตรงที่เดิมและเตรียม'+v.food+' กลิ่นอาหารค่อย ๆ แทนที่กลิ่นถนนบนเสื้อ',child?(childAge<4?child.name+'หลับอยู่ใกล้ ๆ คุณวางของเบามือและเตรียมอาหารกับที่นอนให้เขาปลอดภัย':childAge<16?child.name+'นำสิ่งที่ลองทำระหว่างวันมาให้ดู คุณวางงานครู่หนึ่งแล้วชวนเล่าตั้งแต่เริ่ม':child.name+'แวะมาคุยเรื่องที่กำลังทำในชีวิตตนเอง คุณฟังก่อนถามว่าอยากได้คำแนะนำหรืออยากให้รับฟัง'):FamilyWorld.partnerAlive(s)?s.partner+'เลื่อนถ้วยมาทางคุณและถามว่าวันนี้เหนื่อยไหม คุณพบว่าตนไม่จำเป็นต้องตอบว่าไม่เหนื่อยทุกครั้ง':'คุณจัดที่นั่งให้รับลมพอดี แล้วกินช้ากว่าตอนอยู่ข้างนอก ห้องนี้ไม่ได้สมบูรณ์แบบ แต่มีสิ่งที่ค่อย ๆ จัดจนเข้ามือ'];key='home-'+d.sequence%3;fx='rest'}
}
const need=needs(s,d);if(need)paragraphs.push(need);else if(s.pet&&d.sequence%3===0)paragraphs.push(s.pet.name+'ขยับเข้ามาใกล้ คุณวางมือให้มันเป็นฝ่ายเข้ามาหา เมื่อมันยอมอยู่ข้าง ๆ จึงค่อยเกาคอให้เบา ๆ');else if(s.retainer&&d.sequence%4===0)paragraphs.push('คุณแบ่งงานกับ'+s.retainer+'และถามความเห็นก่อนตัดสินใจร่วมกัน การเดินทางจะไปต่อได้เมื่อทั้งสองคนยังมีพื้นที่พูด');
const entry=append(s,{title,paragraphs,kind,key,phase:v.phase,season:v.season});effect(s,fx);return entry}
function observe(s,event,choice,success,text){if(typeof LifeStories!=='undefined')LifeStories.observe(s,event,choice,success,text);const d=ensure(s);d.memories.unshift({id:event.id,title:event.title,choice:choice.label,result:text,age:s.age});d.memories.length=Math.min(d.memories.length,24);const c=event.context||WorldLore.context(s,s.turn);const prose=WorldLore.fill(s,event.text,c);append(s,{title:WorldLore.fill(s,event.title,c),paragraphs:[prose,WorldLore.fill(s,choice.label,c)+' — '+WorldLore.fill(s,text,c)],kind:'decision',tone:event.critical?'critical':'important',key:'decision-'+event.id,choice:choice.label,scene:event.scene,guest:typeof VisualMemory==='undefined'?null:VisualMemory.actor(s,event.context),where:KINGDOMS[s.kingdom][0]});if(event.id==='friend'&&success){const known=d.people.find(p=>p.id==='friend');if(!known)d.people.push({id:'friend',name:event.context.npc,role:'เพื่อนตั้งแต่วัยเด็ก',trust:55})}if(event.id==='school'&&success){const p=d.people.find(p=>p.id==='mentor');p.trust=Math.min(100,p.trust+10)}}
function interact(s,id,action){if(s.dead)return false;const d=ensure(s),p=d.people.find(p=>p.id===id),moment=s.calendar?.count??s.turn;if(!p||p.alive===false||p.memberId&&!FamilyWorld.list(s).find(m=>m.id===p.memberId)?.alive||!['talk','help','share'].includes(action)||d.interaction[id]===moment)return false;if(id==='mentor'&&Engine.biological(s)<9)return false;if(action==='help'&&Engine.biological(s)<6||action==='share'&&Engine.biological(s)<4)return false;if(action==='share'&&s.gold<4)return false;d.interaction[id]=moment;if(action==='share')s.gold-=4;p.trust=Math.min(100,p.trust+(action==='help'?7:5));if(p.memberId)FamilyWorld.adjust(s,p.memberId,action==='help'?7:5);s.bond=Math.min(100,s.bond+2);d.social=Math.min(100,d.social+10);const tasks={talk:['บทสนทนาที่ไม่ต้องรีบจบ','คุณถาม'+p.name+'ว่าช่วงนี้เป็นอย่างไร แล้วนั่งฟังเรื่องที่เขาไม่ค่อยได้เล่าให้ใครฟัง','ก่อนแยกกัน เขาถามเรื่องของคุณกลับ ความสัมพันธ์ขยับไปอีกนิดจากการฟังกันจนจบ'],help:['ช่วยกันทำเรื่องธรรมดา','คุณเห็น'+p.name+'กำลังจัดของจึงถามว่ามีส่วนไหนให้ช่วยไหม เขาขยับพื้นที่ข้างตัวให้และแบ่งงานที่ทำคู่กันได้','งานเสร็จช้ากว่าการรีบทำลำพังเล็กน้อย แต่ทั้งสองคนได้เรียนรู้จังหวะของกันและกัน'],share:['มื้อที่แบ่งให้กัน','คุณใช้ทองสี่ทองเตรียมของกินง่าย ๆ แล้วชวน'+p.name+'มานั่งด้วยกัน','คุณคุยเรื่องที่อยากทำในวันหน้า เขาไม่ได้มีคำตอบให้ทุกอย่าง แต่ตั้งใจฟังและจำเรื่องที่คุณกังวลไว้']};const a=tasks[action];append(s,{title:a[0],paragraphs:typeof LifeStories==='undefined'?a.slice(1):LifeStories.dialogue(s,p,action),kind:'interaction',key:'interaction-'+id+'-'+moment});return true}
function activity(s,key){if(s.dead||!s.accepted||s.calendar?.pending||s.outcome||!['family','explore','practice','rest'].includes(key))return false;const d=ensure(s),c=Simulation.ensure(s);if(c.actionQuarter===c.count)return false;const n=c.count,rel=FamilyWorld.chooseRelative(s,n),v=context(s),age=Engine.biological(s);let title,paragraphs;if(age<4){s.joy=Math.min(100,s.joy+1);s.bond=Math.min(100,s.bond+1);title=key==='rest'?'พักในที่คุ้นเคย':key==='practice'?'ลองขยับและเรียนรู้':key==='explore'?'มองโลกจากใกล้ตัว':'ช่วงเวลาในอ้อมแขน';const living=FamilyWorld.list(s).find(m=>m.alive);paragraphs=[living?`${living.name}ดูแลให้คุณได้พัก กิน และลองเคลื่อนไหวตามแรงที่มี`:'ผู้ดูแลในชุมชนจัดที่นอนและอาหารให้คุณได้พักอย่างปลอดภัย',key==='practice'?'คุณลองคว้าเอื้อมของที่อยู่ใกล้ มือยังพลาดบ้างก่อนจะจับได้นานขึ้น':key==='explore'?'สี แสง และเสียงใกล้หน้าต่างเป็นสิ่งใหม่ คุณมองตามก่อนหันกลับมาหาเสียงที่คุ้นเคย':'กิจวัตรที่มีคนตอบรับช่วยให้คุณค่อย ๆ รู้สึกปลอดภัย'];}else if(key==='family'&&!FamilyWorld.list(s).some(m=>m.alive)){title='เวลาระลึกถึงคนในบ้าน';s.joy=Math.min(100,s.joy+2);paragraphs=['คุณหยิบของที่เก็บไว้จากคนในบ้านและนึกถึงช่วงเวลาที่เคยอยู่ด้วยกัน','คุณจัดของกลับเข้าที่ แล้วเขียนเรื่องที่จำได้ไว้เผื่ออยากอ่านอีกครั้ง']}else if(key==='family'){FamilyWorld.adjust(s,rel.id,6);s.bond=Math.min(100,s.bond+2);s.joy=Math.min(100,s.joy+2);d.social=Math.min(100,d.social+7);title='เวลาที่คุณเลือกอยู่กับ'+rel.name;paragraphs=typeof LifeStories!=='undefined'?LifeStories.dialogue(s,{id:rel.id,memberId:rel.id,name:rel.name,role:rel.role,trust:rel.trust},'talk'):[`คุณแบ่งเวลาอยู่กับ${rel.name}และฟังสิ่งที่เขาอยากเล่า`] }else if(key==='explore'){s.wisdom=Math.min(100,s.wisdom+2);s.joy=Math.min(100,s.joy+1);title='คุณออกสำรวจย่านที่อยู่';paragraphs=[`คุณเดินจากบ้านไปยัง${v.place} ผ่าน${v.landmark} และจดทางลัดที่คนท้องถิ่นใช้`,`มีร้านซ่อมของเล็ก ๆ เปิดใหม่ เจ้าของจำคุณได้หลังคุณช่วยเก็บกล่องที่หล่น`] }else if(key==='practice'){const stat=s.job!==null?JOBS[s.job][1]:s.focus;s[stat]=Math.min(100,s[stat]+2);d.energy=Math.max(20,d.energy-3);title='ช่วงเวลาฝึกสิ่งที่อยากเก่ง';paragraphs=[`คุณใช้เวลาฝึก${s.job!==null?JOBS[s.job][0]:({magic:'เวท',power:'พละกำลัง',wisdom:'ปัญญา',bond:'ความสัมพันธ์',health:'ดูแลสุขภาพ',joy:'งานที่ทำให้มีความสุข'})[stat]||stat} โดยไม่รีบข้ามขั้น`,`ครั้งนี้คุณแก้จุดพลาดได้หนึ่งอย่างและเขียนวิธีฝึกต่อไว้ให้ตัวเอง`] }else{s.health=Math.min(100,s.health+3);s.joy=Math.min(100,s.joy+2);d.energy=Math.min(100,d.energy+10);title='คุณพักและดูแลตัวเอง';paragraphs=[`คุณเว้นงานไว้ก่อน แล้วนั่งพักในที่ที่มองเห็น${v.landmark}`,rel.alive?`${rel.name}นำ${v.food}มาให้และชวนให้คุณพักเท่าที่ต้องการ`:`คุณเตรียม${v.food}ไว้ใกล้ที่นั่ง และยอมเว้นงานออกไปก่อน`] }c.actionQuarter=c.count;if(typeof Ecology!=='undefined'&&s.race!==0){const adapted=Ecology.activity(s,key);if(adapted){append(s,{...adapted,key:'activity-'+key+'-'+n});return true}}append(s,{title,paragraphs,kind:'interaction',key:'activity-'+key+'-'+n,scene:key==='family'?'kitchen':key==='rest'?'bedroom':key==='practice'?age<6?'nursery':s.job!==null?'workshop':'study':'market',where:KINGDOMS[s.kingdom][0]});return true}
function validate(s){const d=s.diary;if(!d)return true;const finite=(n,a,b)=>typeof n==='number'&&Number.isFinite(n)&&n>=a&&n<=b;return d.version===1&&Number.isInteger(d.sequence)&&finite(d.sequence,0,100000)&&Array.isArray(d.entries)&&d.entries.length<=360&&d.entries.every(e=>e&&typeof e.title==='string'&&e.title.length<300&&Array.isArray(e.paragraphs)&&e.paragraphs.length<=5&&e.paragraphs.every(t=>typeof t==='string'&&t.length<1500)&&finite(e.age,0,10000)&&Number.isInteger(e.id)&&typeof e.phase==='string'&&typeof e.season==='string'&&typeof e.where==='string')&&Array.isArray(d.people)&&d.people.length<=12&&d.people.every(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&p.name.length<100&&typeof p.role==='string'&&finite(p.trust,0,100))&&Array.isArray(d.memories)&&d.memories.length<=24&&d.memories.every(m=>m&&['id','title','choice','result'].every(k=>typeof m[k]==='string'&&m[k].length<1000)&&finite(m.age,0,10000))&&d.arcs&&typeof d.arcs==='object'&&Object.entries(d.arcs).every(([k,v])=>C.arcs.some(a=>a.id===k)&&Number.isInteger(v)&&v>=0&&v<=3)&&finite(d.energy,0,100)&&finite(d.comfort,0,100)&&finite(d.social,0,100)&&d.yearBudget&&finite(d.yearBudget.year,-1,10000)&&finite(d.yearBudget.count,0,3)&&Array.isArray(d.recent)&&d.interaction&&typeof d.interaction==='object'}
return {ensure,append,passage,observe,interact,activity,validate,stage,context};})();
